@page "/chat"
@rendermode InteractiveServer
@using sv_8833d17d0e1943bfa4cbb3e13e71361d.Components.Chat
@using sv_8833d17d0e1943bfa4cbb3e13e71361d.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(isThreadOpen ? "with-thread" : "")">
        @if (isLoadingMore)
        {
            <div class="text-center p-2">
                <button class="btn btn-sm btn-outline-secondary" disabled>
                    <span class="spinner-border spinner-border-sm"></span> Loading…
                </button>
            </div>
        }
        else if (hasMoreMessages)
        {
            <div class="text-center p-2">
                <button class="btn btn-sm btn-outline-secondary" @onclick="LoadOlderMessages">
                    Load older messages
                </button>
            </div>
        }
        <MessageArea Messages="messages"
                     CurrentChannel="SelectedChannel"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadOlderMessages="LoadOlderMessages" />
    </div>

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnSendReply="SendThreadReply"
                     OnClose="CloseThread" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private int selectedChannelId;
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private Channel? SelectedChannel => channels.Find(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        messages = [];
        threadReplyCounts = [];
        hasMoreMessages = true;
        CloseThread();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        await UpdateThreadCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        hasMoreMessages = older.Count >= PageSize;
        messages.InsertRange(0, older);
        await UpdateThreadCounts();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var newMessage = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(newMessage);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.Find(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count in the main view
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction state
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
    }

    private async Task UpdateThreadCounts()
    {
        // Build reply counts from messages that are replies
        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            threadReplyCounts.TryGetValue(rootId, out var count);
            threadReplyCounts[rootId] = count + 1;
        }

        await Task.CompletedTask;
    }
}

/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d42;
    color: #edf2f4;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1a1b2e;
}

::deep .sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8d99ae;
    border-bottom: 1px solid #3a3d56;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
}

::deep .channel-item {
    padding: 0.6rem 1rem;
    cursor: pointer;
    position: relative;
    border-bottom: 1px solid #3a3d56;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #3a3d56;
}

::deep .channel-item.active {
    background: #4a4d6a;
    border-left: 3px solid #ef233c;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-desc {
    font-size: 0.75rem;
    color: #8d99ae;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    top: 0.6rem;
    right: 0.8rem;
    font-size: 0.7rem;
}

/* ===== Main Message Area ===== */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .channel-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
    background: #fff;
}

::deep .channel-header h5 {
    margin: 0;
