    font-size: 0.75rem;
    color: #6c757d;
}

::deep .message-content {
    margin-top: 2px;
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* ===== Reactions ===== */
::deep .reaction-bar {
    display: flex;
    gap: 0.3rem;
    margin-top: 0.3rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 1rem;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
