    transition: background 0.1s;
}

::deep .emoji-picker button:hover {
    background: #e9ecef;
}

/* ===== Message Input ===== */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #dee2e6;
    background: #fff;
    align-items: flex-end;
}

::deep .message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.5rem;
    font-size: 0.9rem;
