}

::deep .message-input textarea:focus {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.2rem rgba(13,110,253,0.25);
}

/* ===== Thread Panel ===== */
::deep .thread-panel {
    width: 25%;
    min-width: 250px;
